mapper.select:
SELECT p.id, p.payment_no, p.bill_id, p.pay_amount, p.pay_method, p.pay_time, p.receipt_no, p.create_time, b.bill_no, o.owner_name, h.house_number, u.full_name as operator_name FROM payment_record p LEFT JOIN bill_info b ON p.bill_id = b.id AND b.is_deleted = 0 LEFT JOIN owner_info o ON p.owner_id = o.id AND o.is_deleted = 0 LEFT JOIN house_info h ON p.house_id = h.id AND h.is_deleted = 0 LEFT JOIN sys_user_info u ON p.operator_id = u.id AND u.is_deleted = 0 WHERE p.is_deleted = 0
AND p.payment_no LIKE CONCAT('%', #{paymentNo}, '%')
AND p.bill_id = #{billId}
AND p.owner_id = #{ownerId}
AND p.house_id = #{houseId}
AND p.pay_method = #{payMethod}
AND p.pay_time >= #{startTime}
AND p.pay_time <= #{endTime}
ORDER BY p.pay_time DESC
